function allocate(totalMinor, ratios) {
  const sum = ratios.reduce((a, b) => a + b, 0);
  const shares = ratios.map((r) => Math.floor((totalMinor * r) / sum));
  let left = totalMinor - shares.reduce((a, b) => a + b, 0);
  const order = ratios
    .map((r, i) => ({ i, rem: (totalMinor * r) % sum }))
    .sort((a, b) => b.rem - a.rem || a.i - b.i);
  for (let j = 0; left > 0; j++, left--) shares[order[j].i] += 1;
  return shares;
}

allocate(10000, [1, 1, 1]);   // [3334, 3333, 3333]
allocate(1001, [70, 20, 10]); // [701, 200, 100]
